H.line(L, (T + B) / 2 - 14, L, (T + B) / 2 + 14, { color: H.colors.warn, width: 4 });
H.line(L - 7, (T + B) / 2 - 7, L + 7, (T + B) / 2 - 7, { color: H.colors.ink, width: 3 });
H.text("Vs " + Vs.toFixed(1) + "V", L - 12, (T + B) / 2 + 4, { color: H.colors.warn, size: 12, align: "right" });
H.rect((L + Rr) / 2 - 26, T - 9, 52, 18, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 3 });
H.text("R1", (L + Rr) / 2, T + 5, { color: H.colors.accent, size: 12, align: "center" });
H.rect(Rr - 9, (T + B) / 2 - 26, 18, 52, { fill: H.colors.panel, stroke: H.colors.accent2, width: 2, radius: 3 });
H.text("R2", Rr + 14, (T + B) / 2 + 4, { color: H.colors.accent2, size: 12, align: "center" });
const top = Rr - L, side = B - T;
const peri = 2 * (top + side);
const speed = 40 + I * 60;
const N = 12;
